import pandas as pd

def parse_signup_dates(texts):
    """Parse sign-up dates typed in by users; some are day-month-year, some year-month-day."""
    # Define custom date parsing function
    def custom_parser(date_str):
        for fmt in ("%d-%m-%Y", "%Y-%m-%d"):
            try:
                return pd.to_datetime(date_str, format=fmt)
            except ValueError:
                continue
        raise ValueError(f"Unparseable date: {date_str}")

    # Apply custom parser to each element in the input list
    return pd.Series([custom_parser(date) for date in texts])
```

