```python
import numpy as np

def safe_sum(arr, axis):
    """Sum the array along the axis; return None if the array has no such axis."""
    try:
        return np.sum(arr, axis=axis)
    except AttributeError as e:
        if "module 'numpy' has no attribute 'AxisError'" in str(e):
            return None
        raise
```

